import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
public final class Deduplicator {
    private final Map<String, Set<String>> seen = new ConcurrentHashMap<String, Set<String>>();
    public synchronized boolean claim(String tenant, String eventId) {
        if (tenant == null || tenant.isEmpty() || eventId == null || eventId.isEmpty()) {
            throw new IllegalArgumentException("tenant and eventId are required");
        }
        Set<String> events = seen.get(tenant);
        if (events == null) {
            events = new HashSet<String>();
            Set<String> existing = seen.putIfAbsent(tenant, events);
            if (existing != null) {
                events = existing;
            }
        }
        return events.add(eventId);
    }
}

