import java.util.*;
public class T {
  public static void main(String[] a) {
    TenantRepository r = new TenantRepository(Arrays.asList(
      new TenantRepository.Row("A","same","a1"),
      new TenantRepository.Row("B","same","b1"),
      new TenantRepository.Row("A","other","a2")));
    List<TenantRepository.Row> fa = r.findAll("A");
    if (fa.size()!=2) throw new Error("findAll size "+fa.size());
    for (TenantRepository.Row row: fa) if (!row.tenant.equals("A")) throw new Error("leak");
    TenantRepository.Row one = r.findOne("A","same");
    if (!one.value.equals("a1")) throw new Error("findOne wrong");
    if (r.findOne("missing","same")!=null) throw new Error("missing should be null");
    fa.clear();
    List<TenantRepository.Row> again = r.findAll("A");
    if (again.size()!=2) throw new Error("mutated state");
    System.out.println("ALL OK");
  }
}
EOF
