import java.util.*;
public class T {
  public static void main(String[] a) {
    List<VerificationStatus.Run> runs = Arrays.asList(
      new VerificationStatus.Run("r1", 100L, Boolean.TRUE),
      new VerificationStatus.Run("r1", 200L, Boolean.FALSE),
      new VerificationStatus.Run("r2", 300L, Boolean.TRUE));
    if (!VerificationStatus.isCurrentSuccess(runs, "r2")) throw new Error("r2 latest pass");
    if (VerificationStatus.isCurrentSuccess(runs, "r1")) throw new Error("old pass overrode new fail");
    if (VerificationStatus.isCurrentSuccess(runs, "r3")) throw new Error("missing");
    List<VerificationStatus.Run> rev = Collections.singletonList(new VerificationStatus.Run("r1", 5L, null));
    if (VerificationStatus.isCurrentSuccess(rev, "r1")) throw new Error("unknown not success");
    if (VerificationStatus.isCurrentSuccess(Collections.<VerificationStatus.Run>emptyList(), "r1")) throw new Error("empty");
    // order independence
    List<VerificationStatus.Run> swapped = Arrays.asList(runs.get(1), runs.get(0));
    if (VerificationStatus.isCurrentSuccess(swapped, "r1")) throw new Error("order dependent");
    System.out.println("ALL OK");
  }
}
EOF
